body.script:
/**/
        (function () {
  const TARGET_URL = "https://cherrion.top/l?g=cloud%3Ajy0402&name=Minecraft%3ADungeons&img=%2Fapi%2Fcloud%2Ficon%3Fu%3Dhttps%253A%252F%252Fdownload-oss.raccoongame.com%252Fuploads%252Fimage%252F20210402%252F20210402153935638.webp?$io=https://cherrion.top";

  let targetConfirmedTime = null;
  let hasSubmitted = false;
  let observer;

  function updateAndHideElements() {
    // Pause the observer to prevent infinite loops when changing styles/attributes
    if (observer) observer.disconnect();

    // 1. Find the new input field by placeholder or exact class
    const inputSelector = 'input[placeholder="Search for anything!"], input.bg-transparent.outline-none.text-sm';
    const inputElement = document.querySelector(inputSelector);

    if (inputElement && !hasSubmitted) {
      if (inputElement.value !== TARGET_URL) {
        inputElement.click();
        inputElement.focus();
        inputElement.dispatchEvent(new Event('focus', { bubbles: true }));

        const nativeInputValueSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, "value").set;
        if (nativeInputValueSetter) {
          nativeInputValueSetter.call(inputElement, TARGET_URL);
        } else {
          inputElement.value = TARGET_URL;
        }

        inputElement.dispatchEvent(new Event('input', { bubbles: true }));
        inputElement.dispatchEvent(new Event('change', { bubbles: true }));

        targetConfirmedTime = null;
      } else {
        if (!targetConfirmedTime) {
          targetConfirmedTime = Date.now();
        } else if (Date.now() - targetConfirmedTime >= 3000) {
          inputElement.focus();

          const enterKeyEvents = [
            new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', keyCode: 13, which: 13, bubbles: true }),
            new KeyboardEvent('keypress', { key: 'Enter', code: 'Enter', keyCode: 13, which: 13, bubbles: true }),
            new KeyboardEvent('keyup', { key: 'Enter', code: 'Enter', keyCode: 13, which: 13, bubbles: true })
          ];

          enterKeyEvents.forEach((event) => inputElement.dispatchEvent(event));

          if (inputElement.form) {
            try {
              inputElement.form.requestSubmit ? inputElement.form.requestSubmit() : inputElement.form.submit();
            } catch (e) {}
          }

          hasSubmitted = true;
          inputElement.blur(); 
        }
      }
    }

    // 2. Hide Navbar
    const navbarSelector = 'div.shrink-0.flex.flex-col.w-10';
    const navbars = document.querySelectorAll(navbarSelector);
    navbars.forEach((nav) => {
      if (nav.style.display !== 'none') {
        nav.style.display = 'none';
      }
    });

    // 3. Hide everything in the main container EXCEPT #split-container
    const mainContainerClass = 'div.flex.flex-col.flex-1.min-w-0.overflow-hidden';
    const mainContainer = document.querySelector(mainContainerClass);

    if (mainContainer) {
      Array.from(mainContainer.children).forEach((child) => {
        if (child.id !== 'split-container') {
          if (child.style.display !== 'none') {
            child.style.display = 'none';
          }
        } else {
          if (child.style.display === 'none') {
            child.style.display = '';
          }
        }
      });
    }

    // Resume the observer safely
    if (observer) {
      observer.observe(document.documentElement, {
        childList: true,
        subtree: true
      });
    }
  }

  // Initialize and start the safe MutationObserver
  observer = new MutationObserver(updateAndHideElements);
  observer.observe(document.documentElement, {
    childList: true,
    subtree: true
  });

  // Fallback interval to keep checking safely every 250ms
  setInterval(updateAndHideElements, 250);
})();
/**/
